  "Ask Mnemo what is overdue across your boards; it can tick cards off or move them for you, and agents get the same over MCP.": "Frag Mnemo, was auf deinen Boards überfällig ist; es kann Karten für dich abhaken oder verschieben, und Agenten bekommen dasselbe über MCP.",
  "Ask about the folder {name}, or anything in your vault.": "Frag zum Ordner {name} oder zu allem in deinem Tresor.",
