  "Browsers signed in to your account. Tap ⋯ to name a device, see its sign-ins or sign it out. Connected agents are not listed here and keep working.": "Browser, die in deinem Konto angemeldet sind. Tippe auf ⋯, um ein Gerät zu benennen, seine Anmeldungen zu sehen oder es abzumelden. Verbundene Agenten stehen hier nicht und funktionieren weiter.",
