  "Button does nothing? Choose <b>Copy setup instead</b> and paste it into <code>~/.cursor/mcp.json</code> (create the file when missing).": "Passiert beim Klick nichts? Wähle <b>Stattdessen Setup kopieren</b> und füge es in <code>~/.cursor/mcp.json</code> ein (lege die Datei an, falls sie fehlt).",
  "Button does nothing? Choose <b>Copy setup instead</b>, run <b>MCP: Open User Configuration</b> from the Command Palette and paste it there. VS Code uses <code>servers</code>, not <code>mcpServers</code>.": "Passiert beim Klick nichts? Wähle <b>Stattdessen Setup kopieren</b>, führe in der Befehlspalette <b>MCP: Open User Configuration</b> aus und füge es dort ein. VS Code nutzt <code>servers</code>, nicht <code>mcpServers</code>.",
