  "Chat with a model you choose; {mnemo} reads, writes, tags, links, moves and tidies notes with Memora's own tools. It cannot browse the web, run commands, delete for good or change the server. Keys are sealed on this server and never sent to the browser.": "Chatte mit einem Modell deiner Wahl; {mnemo} liest, schreibt, taggt, verlinkt, verschiebt und ordnet Notizen mit den eigenen Tools von Memora. Es kann nicht im Web surfen, keine Befehle ausführen, nichts endgültig löschen und den Server nicht ändern. Schlüssel sind auf diesem Server versiegelt und gehen nie an den Browser.",
