  "Claude and ChatGPT sign in with your Memora account. Nothing to copy.": "Claude und ChatGPT melden sich mit deinem Memora-Konto an. Nichts zu kopieren.",
  "Claude models": "Claude-Modelle",
  "Claude signs in over OAuth, so no key is pasted: it gets its own key when you press Allow. Without sign-in, connect it as <b>Other app</b> and send the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Claude meldet sich über OAuth an, daher wird kein Schlüssel eingefügt: Es bekommt einen eigenen Schlüssel, wenn du auf Erlauben tippst. Ohne Anmeldung verbinde es als <b>Andere App</b> und sende den Header <code>Authorization: Bearer &lt;key&gt;</code>.",
  "Claude, ChatGPT, Cursor and more": "Claude, ChatGPT, Cursor und mehr",
  "Claude, ChatGPT, Cursor and more, each with its own key": "Claude, ChatGPT, Cursor und mehr, jeweils mit eigenem Schlüssel",
  "Claude, ChatGPT, Cursor, Codex and others each get their own access, so you can see what each one does.": "Claude, ChatGPT, Cursor, Codex und andere bekommen jeweils eigenen Zugriff, sodass du siehst, was jeder tut.",
  "Claude, Cursor, ChatGPT and your own agent share one Memora, reachable from this computer, the local network or the internet": "Claude, Cursor, ChatGPT und dein eigener Agent teilen sich ein Memora, erreichbar von diesem Computer, dem lokalen Netzwerk oder dem Internet",
