  "Deleted by {who}": "Gelöscht von {who}",
  "Deleted chats and their messages are gone for good. Your notes are not touched, and a chat that is answering right now is left alone.": "Gelöschte Chats und ihre Nachrichten sind endgültig weg. Deine Notizen bleiben unberührt, und ein Chat, der gerade antwortet, bleibt unangetastet.",
  "Deleted notes": "Gelöschte Notizen",
  "Deleted notes wait here until you restore them or delete them forever. When you restore, you choose where the note goes: its old folder, another folder or the top level.": "Gelöschte Notizen warten hier, bis du sie wiederherstellst oder endgültig löschst. Beim Wiederherstellen wählst du, wohin die Notiz kommt: in ihren alten Ordner, einen anderen Ordner oder auf die oberste Ebene.",
