  "Drag a card into another folder frame to move the note on disk. Drag a frame by its name to rearrange the board; drop it onto another frame to move the whole folder there. Double-click a title to rename. On touch: drag to pan, pinch to zoom, long-press a card to move it, tap to preview.": "Zieh eine Karte in einen anderen Ordnerrahmen, um die Notiz auf der Festplatte zu verschieben. Zieh einen Rahmen am Namen, um das Board umzuordnen; lass ihn auf einem anderen Rahmen fallen, um den ganzen Ordner dorthin zu verschieben. Doppelklicke einen Titel zum Umbenennen. Per Touch: ziehen zum Verschieben der Ansicht, zwei Finger zum Zoomen, Karte lange drücken zum Verschieben, tippen für die Vorschau.",
  "Drag a note here to pin it": "Zieh eine Notiz hierher, um sie anzuheften",
  "Drag notes or folders here to pin them": "Zieh Notizen oder Ordner hierher, um sie anzuheften",
  "Drag notes or folders onto a folder to move them, onto Pinned to pin them.": "Zieh Notizen oder Ordner auf einen Ordner, um sie zu verschieben, oder auf Angeheftet, um sie anzuheften.",
  "Drag notes · double-click to pin · / search · #tag finds tags · F fit · 1 2 3 layouts": "Notizen ziehen · Doppelklick zum Anheften · / Suche · #Tag findet Tags · F einpassen · 1 2 3 Layouts",
  "Drag to move the folder frame; double-click to rename": "Ziehen, um den Ordnerrahmen zu verschieben; Doppelklick zum Umbenennen",
  "Drag to move the lane. Double click the name to rename it.": "Zum Verschieben der Spalte ziehen. Doppelklick auf den Namen zum Umbenennen.",
  "Drag to resize · double-click to reset": "Zum Skalieren ziehen · Doppelklick zum Zurücksetzen",
  "Drag to turn · scroll to zoom · click a point to open its note": "Ziehen zum Drehen · Scrollen zum Zoomen · Punkt anklicken, um die Notiz zu öffnen",
  "Drag to turn · scroll to zoom · click a point to open its note · / to search · #tag finds tags": "Ziehen zum Drehen · Scrollen zum Zoomen · Punkt anklicken, um die Notiz zu öffnen · / zum Suchen · #Tag findet Tags",
  "Draw a chart of how many notes I write each week": "Zeichne ein Diagramm, wie viele Notizen ich pro Woche schreibe",
  "Draw this note as a diagram": "Diese Notiz als Diagramm zeichnen",
  "Drop a card here or add one": "Zieh eine Karte hierher oder füge eine hinzu",
  "Drop here to hide": "Hier ablegen zum Ausblenden",
