  "Duration": "Dauer",
  "Dusk": "Abenddämmerung",
  "Dyslexic": "Legasthenie",
  "Each AI app connects over MCP with its own key and permissions.": "Jede KI-App verbindet sich über MCP mit eigenem Schlüssel und eigenen Rechten.",
  "Each AI app you connect is an agent with its own key, so you see what each one does and can turn one off on its own.": "Jede KI-App, die du verbindest, ist ein Agent mit eigenem Schlüssel. So siehst du, was jede tut, und kannst eine einzeln ausschalten.",
  "Each agent": "Jeder Agent",
  "Each agent belongs to one app. For another app or device, make a new agent.": "Jeder Agent gehört zu einer App. Für eine andere App oder ein anderes Gerät erstelle einen neuen Agenten.",
  "Each agent belongs to one app. To use Memora in another app, create a separate agent for it.": "Jeder Agent gehört zu einer App. Um Memora in einer anderen App zu nutzen, erstelle dafür einen eigenen Agenten.",
  "Each app gets its own key": "Jede App bekommt einen eigenen Schlüssel",
  "Each has a short id that never changes, so names can change freely. Mnemo sets them up, changes their instructions or model, messages, waits for, stops, finishes and removes them, one or all at once, and can let them work in the background. Each card shows Instruction, Activity and Answer.": "Jeder hat eine kurze ID, die sich nie ändert, Namen sind also frei änderbar. Mnemo legt sie an, ändert Anweisungen oder Modell, schreibt ihnen, wartet auf sie, stoppt, beendet und entfernt sie, einzeln oder alle auf einmal, und lässt sie auch im Hintergrund arbeiten. Jede Karte zeigt Auftrag, Aktivität und Antwort.",
  "Each kind is measured against its own room: its limit when set, else what it uses plus the free disk space{disk}. Empty limit: none.": "Jede Art wird an ihrem eigenen Platz gemessen: ihrem Limit, falls gesetzt, sonst dem, was sie belegt, plus freiem Speicherplatz{disk}. Leeres Limit: keins.",
  "Each one gets its own key from Memora.": "Jeder bekommt von Memora einen eigenen Schlüssel.",
  "Earlier": "Früher",
  "Earlier version": "Frühere Version",
  "Easier on the eyes": "Schonender für die Augen",
  "Edge to edge": "Randlos",
  "Edit": "Bearbeiten",
  "Edit (E)": "Bearbeiten (E)",
