  "Entries": "Einträge",
  "Error": "Fehler",
  "Error 404": "Fehler 404",
  "Even in daily use, a browser signs in again after this long. It cannot be shorter than the inactivity time.": "Auch bei täglicher Nutzung meldet sich ein Browser nach dieser Zeit neu an. Sie kann nicht kürzer sein als die Inaktivitätszeit.",
  "Every AI loses {n} tool at once. Asks first.": "Jede KI verliert {n} Tool auf einmal. Fragt zuerst.",
  "Every AI loses {n} tools at once. Asks first.": "Jede KI verliert {n} Tools auf einmal. Fragt zuerst.",
  "Every Kanban board in your notes": "Jedes Kanban-Board in deinen Notizen",
  "Every action, newest first": "Jede Aktion, neueste zuerst",
  "Every action, newest first, with search and filters.": "Jede Aktion, neueste zuerst, mit Suche und Filtern.",
  "Every address from one to another.": "Jede Adresse von einer bis zur anderen.",
  "Every address from the first to the last, joined by a dash.": "Jede Adresse von der ersten bis zur letzten, mit Bindestrich verbunden.",
  "Every agent usually starts from zero. {bold} connect each agent once and they all read the same vault and write back to it, so what one learns, the others can use.": "Jeder Agent fängt meist bei null an. {bold} Verbinde jeden Agenten einmal, und alle lesen denselben Tresor und schreiben darin zurück. Was einer lernt, können die anderen nutzen.",
  "Every archived card is back on the board": "Jede archivierte Karte ist wieder auf dem Board",
  "Every board with its lanes and progress. New board sits wherever New note does: the sidebar, Overview, folders, menus, search and the B key.": "Jedes Board mit seinen Spalten und seinem Fortschritt. Neues Board steht überall, wo Neue Notiz steht: in der Seitenleiste, der Übersicht, in Ordnern, Menüs, der Suche und auf der Taste B.",
  "Every browser and agent is disconnected until someone starts Memora again on that machine. This page cannot start it again.": "Jeder Browser und jeder Agent wird getrennt, bis jemand Memora auf diesem Rechner wieder startet. Diese Seite kann es nicht neu starten.",
  "Every call shows up live in the brain and Activity": "Jeder Aufruf erscheint live im Gehirn und in der Aktivität",
  "Every change Mnemo makes shows in Activity and can be undone from History.": "Jede Änderung von Mnemo erscheint in der Aktivität und lässt sich im Verlauf rückgängig machen.",
  "Every change, by you or an app, shows in Activity and can be undone from History.": "Jede Änderung, von dir oder einer App, erscheint in der Aktivität und lässt sich im Verlauf rückgängig machen.",
  "Every chat is archived.": "Jeder Chat ist archiviert.",
  "Every chat with your notes agent": "Jeder Chat mit deinem Notizen-Agenten",
  "Every connected AI loses all {n} tools at once and can no longer read or change your notes until you turn tools back on here.": "Jede verbundene KI verliert alle {n} Tools auf einmal und kann deine Notizen nicht mehr lesen oder ändern, bis du hier die Tools wieder einschaltest.",
  "Every connected AI loses it at once. You can turn it back on any time.": "Jede verbundene KI verliert es auf einmal. Du kannst es jederzeit wieder einschalten.",
  "Every connected AI loses them at once. You can turn them back on any time.": "Jede verbundene KI verliert sie auf einmal. Du kannst sie jederzeit wieder einschalten.",
  "Every connected agent loses its memory until Memora runs again.": "Jeder verbundene Agent verliert sein Gedächtnis, bis Memora wieder läuft.",
  "Every device on a home or office network, written as address/size: 192.168.1.0/24 covers 192.168.1.0 to 192.168.1.255.": "Jedes Gerät in einem Heim- oder Büronetzwerk, geschrieben als Adresse/Größe: 192.168.1.0/24 umfasst 192.168.1.0 bis 192.168.1.255.",
  "Every device on a home or office network.": "Jedes Gerät in einem Heim- oder Büronetzwerk.",
  "Every image in the notes folder and where it is shown, and the pictures kept for Mnemo chats.": "Jedes Bild im Notizordner und wo es gezeigt wird, dazu die Bilder der Mnemo-Chats.",
  "Every image is used in a note.": "Jedes Bild wird in einer Notiz verwendet.",
  "Every note": "Jede Notiz",
  "Every note and link, in 3D, as a graph or on a board.": "Jede Notiz und jeder Link, in 3D, als Graph oder auf einem Board.",
  "Every note and subfolder in \"{path}\" moves into {folder}; \"{name}\" is then removed. If a name is already taken there, a number is added to it.": "Jede Notiz und jeder Unterordner in „{path}“ wird nach {folder} verschoben; „{name}“ wird danach entfernt. Ist dort ein Name schon vergeben, wird eine Nummer angehängt.",
  "Every note becomes a card here, inside a frame for its folder. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Jede Notiz wird hier zur Karte, in einem Rahmen für ihren Ordner. Die Anleitung zeigt, wie eine KI ihr Wissen hier speichert oder wie du selbst eine Notiz schreibst.",
  "Every note becomes a point of light here, grouped by folder. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Jede Notiz wird hier zu einem Lichtpunkt, nach Ordner gruppiert. Die Anleitung zeigt, wie eine KI ihr Wissen hier speichert oder wie du selbst eine Notiz schreibst.",
  "Every note tagged #{tag} ({notes}) gets the new name, inline #tags in the text too.": "Jede Notiz mit dem Tag #{tag} ({notes}) bekommt den neuen Namen, auch Inline-#Tags im Text.",
  "Every note tagged {tags} gets one tag instead ({notes}). Inline #tags in the text change too. There is no one-step undo; each note keeps its history.": "Jede Notiz mit {tags} bekommt stattdessen einen Tag ({notes}). Auch Inline-#Tags im Text ändern sich. Es gibt kein Rückgängig in einem Schritt; jede Notiz behält ihren Verlauf.",
  "Every read and write by an agent shows up live, so you always know who did what.": "Jedes Lesen und Schreiben eines Agenten erscheint live, sodass du immer weißt, wer was getan hat.",
  "Every request that reaches this rule is {verb}.": "Jede Anfrage, die diese Regel erreicht, wird {verb}.",
  "Every request. Put it last, to catch whatever the rules above did not.": "Jede Anfrage. Setze sie ans Ende, um alles aufzufangen, was die Regeln darüber nicht erfassen.",
  "Every setting and where it lives.": "Jede Einstellung und wo sie zu finden ist.",
  "Every shortcut in the web UI.": "Jedes Kürzel in der Web-Oberfläche.",
  "Every tag and its notes": "Jeder Tag und seine Notizen",
