  "For authentication choose <b>OAuth</b>, leave the client ID and secret empty, and click <b>Create</b>. A Memora page opens: press <b>Allow</b>.": "Wähle als Authentifizierung <b>OAuth</b>, lass Client-ID und Secret leer und klicke auf <b>Create</b>. Eine Memora-Seite öffnet sich: Tippe auf <b>Allow</b>.",
