  "Gathering the real activity for {range}. This can take a moment on a big log, please wait.": "Die echte Aktivität für {range} wird gesammelt. Bei einem großen Protokoll kann das einen Moment dauern, bitte warten.",
  "General": "Allgemein",
  "Get a one-time code on the server": "Einmalcode auf dem Server abrufen",
  "Get started": "Los geht’s",
  "Get to know me from my notes. Look through my vault (recent notes, journals, projects, anything about me) and keep what you learn with remember_owner: who I am, what I work on, how I like answers, what I like. Short, lasting things only, never secrets. Then tell me in a few lines what you kept.": "Lerne mich über meine Notizen kennen. Sieh dir meinen Tresor an (neue Notizen, Tagebücher, Projekte, alles über mich) und behalte mit remember_owner, was du erfährst: wer ich bin, woran ich arbeite, wie ich Antworten mag, was ich mag. Nur Kurzes und Dauerhaftes, nie Geheimnisse. Sag mir dann in ein paar Zeilen, was du dir gemerkt hast.",
  "Gets its own agent key: read and write nodes over MCP": "Bekommt einen eigenen Agentenschlüssel: Knoten über MCP lesen und schreiben",
  "Getting started": "Erste Schritte",
  "GitHub answered HTTP {code}": "GitHub antwortete mit HTTP {code}",
  "Give Claude, Cursor or any MCP app its own key, then let it save what it already knows about you.": "Gib Claude, Cursor oder jeder MCP-App einen eigenen Schlüssel und lass sie speichern, was sie schon über dich weiß.",
  "Give a key read-only access, or let it write too.": "Gib einem Schlüssel nur Lesezugriff oder erlaube ihm auch Schreiben.",
  "Give each app or device its own agent. Activity then shows exactly who did what, and you can turn one off without touching the others.": "Gib jeder App oder jedem Gerät einen eigenen Agenten. Die Aktivität zeigt dann genau, wer was getan hat, und du kannst einen ausschalten, ohne die anderen zu berühren.",
