  "How Memora looks for you. Saved in this browser only.": "Wie Memora für dich aussieht. Nur in diesem Browser gespeichert.",
  "How far apart the folder islands of the Clusters layout are.": "Wie weit die Ordnerinseln im Cluster-Layout auseinanderliegen.",
  "How far apart the rings of the Radial layout are.": "Wie weit die Ringe im Radial-Layout auseinanderliegen.",
  "How full notes, images and chats are, and their limits": "Wie voll Notizen, Bilder und Chats sind, und ihre Limits",
  "How hard notes push each other apart in the Force layout.": "Wie stark sich Notizen im Kraft-Layout abstoßen.",
  "How it works": "So funktioniert es",
