  "How many notes": "Wie viele Notizen",
  "How much history the server keeps": "Wie viel Verlauf der Server behält",
  "How much room notes, images and Mnemo chats take, each against its own room. A banner warns when one is almost full.": "Wie viel Platz Notizen, Bilder und Mnemo-Chats belegen, jeweils an ihrem eigenen Platz gemessen. Ein Banner warnt, wenn einer fast voll ist.",
  "How the agent itself shows up: its display name and colour.": "Wie der Agent selbst erscheint: sein Anzeigename und seine Farbe.",
  "How to update": "So aktualisierst du",
