  "Humanist": "Humanistisch",
  "Hyphenate long words": "Lange Wörter trennen",
  "I find, read, write, tag, link and tidy your notes. No web, no shell: only your vault.": "Ich finde, lese, schreibe, tagge, verlinke und ordne deine Notizen. Kein Web, keine Shell: nur dein Tresor.",
  "Icon": "Symbol",
  "Icon {name}": "Symbol {name}",
  "Ideas grow when they connect. Link this note to {a} or read {b}.": "Ideen wachsen, wenn sie sich verbinden. Verlinke diese Notiz mit {a} oder lies {b}.",
  "Identity": "Identität",
  "Idle": "Im Leerlauf",
  "If it's been useful to you, a star on GitHub or telling a friend helps others find it. No worries if not.": "Wenn es dir nützlich war, helfen ein Stern auf GitHub oder ein Tipp an einen Freund anderen, es zu finden. Kein Problem, wenn nicht.",
  "If you leave, they are kept on this device and offered again when you open the note.": "Wenn du gehst, bleiben sie auf diesem Gerät und werden dir beim Öffnen der Notiz wieder angeboten.",
  "Image": "Bild",
  "Image (or paste or drop one)": "Bild (oder einfügen oder ablegen)",
  "Image deleted": "Bild gelöscht",
  "Image line copied": "Bildzeile kopiert",
  "Image you attached": "Bild, das du angehängt hast",
  "Image {name}": "Bild {name}",
  "Images": "Bilder",
  "Images can now be up to {n} MB": "Bilder dürfen jetzt bis zu {n} MB groß sein",
  "Images in this folder": "Bilder in diesem Ordner",
  "Images live beside the notes that show them. Choose how large one may be, and see what notes and images take.": "Bilder liegen neben den Notizen, die sie zeigen. Wähle, wie groß eines sein darf, und sieh, was Notizen und Bilder belegen.",
  "Import and export": "Import und Export",
  "Imported": "Importiert",
  "In ChatGPT, open <b>Settings → Apps &amp; Connectors → Advanced settings</b> and turn on <b>Developer mode</b>. Then choose <b>Create</b>.": "Öffne in ChatGPT <b>Settings → Apps &amp; Connectors → Advanced settings</b> und schalte <b>Developer mode</b> ein. Wähle dann <b>Create</b>.",
  "In Claude (web or desktop), open <b>Settings → Connectors</b> and choose <b>Add custom connector</b>.": "Öffne in Claude (Web oder Desktop) <b>Settings → Connectors</b> und wähle <b>Add custom connector</b>.",
  "In Claude Desktop, open <b>Settings → Developer → Edit Config</b>. On newer versions, pick <b>Claude</b> instead.": "Öffne in Claude Desktop <b>Settings → Developer → Edit Config</b>. Bei neueren Versionen wähle stattdessen <b>Claude</b>.",
  "In Windsurf, open <b>Settings → Cascade → MCP servers</b> and choose <b>View raw config</b>.": "Öffne in Windsurf <b>Settings → Cascade → MCP servers</b> und wähle <b>View raw config</b>.",
  "In colour": "Farbig",
  "In note text": "Im Notiztext",
  "In notes": "In Notizen",
  "In search: actions only (new note, theme ...)": "In der Suche: nur Aktionen (neue Notiz, Design …)",
  "In short": "Kurz gesagt",
