  "Installed": "Installiert",
  "Installing, connecting agents, settings and reference.": "Installation, Agenten verbinden, Einstellungen und Referenz.",
  "Instance not ready": "Instanz nicht bereit",
  "Instruction": "Auftrag",
  "Instruction style": "Anweisungsstil",
  "Instructions": "Anweisungen",
  "Instructions from {mnemo}": "Anweisungen von {mnemo}",
  "Interface": "Oberfläche",
  "Internet (tunnel)": "Internet (Tunnel)",
  "Internet address (IP)": "Internetadresse (IP)",
  "It becomes your first rule.": "Sie wird deine erste Regel.",
  "It becomes {path}. Links to its notes keep working.": "Sie wird zu {path}. Links zu ihren Notizen funktionieren weiter.",
  "It can change notes, but nothing lets it connect.": "Er kann Notizen ändern, aber nichts lässt ihn sich verbinden.",
  "It can search and read your notes, but not change them": "Er kann deine Notizen durchsuchen und lesen, aber nicht ändern",
  "It can search, read and save your notes": "Er kann deine Notizen durchsuchen, lesen und speichern",
  "It can {list}.": "Er kann {list}.",
  "It cannot do anything yet": "Er kann noch nichts tun",
  "It has full control: it reads and changes notes, and can manage Memora and other agents": "Er hat volle Kontrolle: Er liest und ändert Notizen und kann Memora und andere Agenten verwalten",
  "It holds {n} note. Next you choose what happens to them: move them to another folder, or move them to the Trash. Nothing is changed yet.": "Er enthält {n} Notiz. Als Nächstes wählst du, was damit passiert: in einen anderen Ordner verschieben oder in den Papierkorb. Noch wird nichts geändert.",
  "It holds {n} notes. Next you choose what happens to them: move them to another folder, or move them to the Trash. Nothing is changed yet.": "Er enthält {n} Notizen. Als Nächstes wählst du, was damit passiert: in einen anderen Ordner verschieben oder in den Papierkorb. Noch wird nichts geändert.",
  "It is added at the end, as rule {n}, so it is checked last.": "Sie wird am Ende als Regel {n} hinzugefügt und daher zuletzt geprüft.",
  "It is gone when you leave, pictures included. Changes to your notes still show in Activity and History.": "Alles verschwindet, wenn du gehst, auch Bilder. Änderungen an deinen Notizen bleiben in Aktivität und Verlauf.",
  "It is kept locked on the server. Enter your Memora password and the buttons below put it in for you.": "Er wird auf dem Server gesperrt gehalten. Gib dein Memora-Passwort ein, und die Buttons unten tragen ihn für dich ein.",
  "It is taking a while. Check the server, then reload this page.": "Es dauert etwas. Prüfe den Server und lade diese Seite neu.",
  "It leaves the Pinned list only; the folder itself stays where it is.": "Er verlässt nur die Liste Angeheftet; der Ordner selbst bleibt, wo er ist.",
  "It leaves the Pinned list only; the note itself stays where it is.": "Sie verlässt nur die Liste Angeheftet; die Notiz selbst bleibt, wo sie ist.",
  "It may have been renamed, moved or deleted. Deleted notes wait in the Trash.": "Sie wurde vielleicht umbenannt, verschoben oder gelöscht. Gelöschte Notizen warten im Papierkorb.",
  "It moves; links to it are updated and pins follow.": "Sie wird verschoben; Links darauf werden aktualisiert und Anheftungen folgen.",
  "It must sign in again and is told why": "Er muss sich neu anmelden und erfährt den Grund",
  "It prints a one-time code. This page moves on by itself.": "Es gibt einen Einmalcode aus. Diese Seite geht von selbst weiter.",
  "It reached Memora but did not finish. It often works on the next try.": "Er hat Memora erreicht, aber nicht abgeschlossen. Oft klappt es beim nächsten Versuch.",
  "It reached Memora but did not finish: {error} It often works on the next try.": "Er hat Memora erreicht, aber nicht abgeschlossen: {error} Oft klappt es beim nächsten Versuch.",
  "It shows up under this name in Activity, the brain and the graph. Name it after the device when you use {app} in more than one place, like \"{example}\".": "Er erscheint unter diesem Namen in Aktivität, Gehirn und Graph. Benenne ihn nach dem Gerät, wenn du {app} an mehreren Orten nutzt, etwa „{example}“.",
  "It was shown when it was made. Make a new key to see one again.": "Er wurde bei der Erstellung gezeigt. Erstelle einen neuen Schlüssel, um einen wieder zu sehen.",
  "Italic": "Kursiv",
  "Its API key and its models are removed. Chats stay; a chat that used one of its models switches to the default.": "Sein API-Schlüssel und seine Modelle werden entfernt. Chats bleiben; ein Chat, der eines seiner Modelle nutzte, wechselt zum Standard.",
  "Its key and access stay the same in every notes folder. Connect another one any time.": "Sein Schlüssel und Zugriff bleiben in jedem Notizordner gleich. Verbinde jederzeit einen weiteren.",
  "Its key is filled in on the next step": "Sein Schlüssel wird im nächsten Schritt eingetragen",
  "Its key is refused until you turn it back on. Nothing is deleted.": "Sein Schlüssel wird abgewiesen, bis du ihn wieder einschaltest. Nichts wird gelöscht.",
  "Its key is refused. Turn it on to let it connect again with the same key.": "Sein Schlüssel wird abgewiesen. Schalte ihn ein, damit er sich mit demselben Schlüssel wieder verbinden darf.",
  "Its key stopped working. You can restore it until you reload the app.": "Sein Schlüssel funktioniert nicht mehr. Du kannst ihn wiederherstellen, bis du die App neu lädst.",
  "Its key stops working at once. Past activity stays; you can restore it until you reload the app.": "Sein Schlüssel funktioniert sofort nicht mehr. Bisherige Aktivität bleibt; du kannst ihn wiederherstellen, bis du die App neu lädst.",
  "Its key was shown only once, when it was made. A new key replaces it and the old one stops working at once.": "Sein Schlüssel wurde nur einmal gezeigt, bei der Erstellung. Ein neuer Schlüssel ersetzt ihn, und der alte funktioniert sofort nicht mehr.",
  "Its notes are in its folders. You can also start one here.": "Seine Notizen liegen in seinen Ordnern. Du kannst hier auch einen starten.",
  "Its numbers, timeline and export.": "Seine Zahlen, Zeitverlauf und Export.",
  "Its old folder is not known, so it goes to the top level": "Sein alter Ordner ist unbekannt, daher kommt sie auf die oberste Ebene",
  "Its page": "Seine Seite",
  "Its page shows how to connect it.": "Seine Seite zeigt, wie du ihn verbindest.",
  "Its page: status, recent calls, access and settings.": "Seine Seite: Status, letzte Aufrufe, Zugriff und Einstellungen.",
  "Its permissions are a custom mix. Pick a level to replace them, or fine-tune them under Advanced.": "Seine Berechtigungen sind eine eigene Mischung. Wähle eine Stufe, um sie zu ersetzen, oder passe sie unter Erweitert an.",
  "Its {n} card goes to the Archive first, where you can restore it to another lane.": "Ihre {n} Karte kommt zuerst ins Archiv, wo du sie in eine andere Spalte zurückholen kannst.",
  "Its {n} cards go to the Archive first, where you can restore them to another lane.": "Ihre {n} Karten kommen zuerst ins Archiv, wo du sie in eine andere Spalte zurückholen kannst.",
