  "Long chats, light": "Lange Chats, leicht",
  "Long enough. A few more characters make it stronger.": "Lang genug. Ein paar Zeichen mehr machen es stärker.",
  "Longer tasks show as a checklist above the message box: not started, in progress, done.": "Längere Aufgaben erscheinen als Checkliste über dem Nachrichtenfeld: nicht begonnen, in Arbeit, erledigt.",
