  "Look for tags that mean the same thing": "Nach Tags suchen, die dasselbe bedeuten",
  "Look through the project in this folder and save it into Memora: what it is for, how it is built, how to run it, technical decisions, and anything worth remembering. Make one note per topic, in a folder named after the project inside Projects.": "Sieh dir das Projekt in diesem Ordner an und speichere es in Memora: wofür es da ist, wie es aufgebaut ist, wie man es startet, technische Entscheidungen und alles, was sich zu merken lohnt. Mach eine Notiz pro Thema, in einem nach dem Projekt benannten Ordner innerhalb von Projects.",
