  "Make an agent for each app or device you use. Each one gets its own key, so you can see what it does and turn it off on its own.": "Erstelle für jede App oder jedes Gerät, das du nutzt, einen Agenten. Jeder bekommt einen eigenen Schlüssel, sodass du siehst, was er tut, und ihn einzeln ausschalten kannst.",
  "Make an index note for my biggest folder": "Erstelle eine Indexnotiz für meinen größten Ordner",
