  "Medium": "Mittel",
  "Medium text": "Mittlerer Text",
  "Meet Mnemo, your notes agent": "Lerne Mnemo kennen, deinen Notiz-Agenten",
  "Memora address (MCP endpoint)": "Memora-Adresse (MCP-Endpunkt)",
  "Memora already uses this folder.": "Memora nutzt diesen Ordner bereits.",
  "Memora by Codrihub Tech": "Memora von Codrihub Tech",
  "Memora can save notes here": "Memora kann hier Notizen speichern",
  "Memora checks the folder and asks you to confirm before it switches. Nothing is moved or copied, and you can switch back here. Running in Docker? Use a folder mounted into the container.": "Memora prüft den Ordner und bittet dich um Bestätigung, bevor es wechselt. Nichts wird verschoben oder kopiert, und du kannst hier zurückwechseln. Läuft es in Docker? Nimm einen in den Container eingebundenen Ordner.",
  "Memora could not start.": "Memora konnte nicht starten.",
  "Memora data folder": "Memora-Datenordner",
  "Memora first checks that the new folder exists (or can be created) and that it can save notes there. If the check fails, nothing changes.": "Memora prüft zuerst, ob der neue Ordner existiert (oder angelegt werden kann) und ob es dort Notizen speichern kann. Schlägt die Prüfung fehl, ändert sich nichts.",
  "Memora first checks that the new folder exists and that it can save notes there. If the check fails, nothing changes.": "Memora prüft zuerst, ob der neue Ordner existiert und ob es dort Notizen speichern kann. Schlägt die Prüfung fehl, ändert sich nichts.",
  "Memora in your language, Mnemo showing its plan as it works, and you choosing what it may use and see.": "Memora in deiner Sprache, Mnemo zeigt bei der Arbeit seinen Plan, und du bestimmst, was es nutzen und sehen darf.",
  "Memora is a notes app your AI apps can use too. You write in it, they read and write the same notes, and you can always see what changed.": "Memora ist eine Notiz-App, die auch deine KI-Apps nutzen können. Du schreibst darin, sie lesen und schreiben dieselben Notizen, und du siehst immer, was sich geändert hat.",
  "Memora is free and open source": "Memora ist kostenlos und Open Source",
  "Memora is free and open source. A star helps others find it.": "Memora ist kostenlos und Open Source. Ein Stern hilft anderen, es zu finden.",
  "Memora is memory, advanced: built to remember what you and your AI learn, and to remember more the more you use it.": "Memora ist Gedächtnis, weitergedacht: gebaut, um sich zu merken, was du und deine KI lernen, und um sich umso mehr zu merken, je mehr du es nutzt.",
  "Memora is restarting": "Memora startet neu",
  "Memora is shut down": "Memora ist heruntergefahren",
  "Memora is still empty. Connect an AI app, send it one prompt, and it saves what it knows about you here, as notes you can read, edit and see in the brain.": "Memora ist noch leer. Verbinde eine KI-App, sende ihr einen Prompt, und sie speichert hier, was sie über dich weiß, als Notizen, die du lesen, bearbeiten und im Gehirn sehen kannst.",
  "Memora keeps a list of your tags to suggest them while you type. Refresh it if a tag is missing or out of date.": "Memora führt eine Liste deiner Tags, um sie beim Tippen vorzuschlagen. Aktualisiere sie, wenn ein Tag fehlt oder veraltet ist.",
  "Memora keeps every version of a note when the vault folder is a git repository. Run {cmd} in the vault folder once (see Configuration, “Version history” in the docs); from then on every change is kept here.": "Memora behält jede Version einer Notiz, wenn der Tresor-Ordner ein Git-Repository ist. Führe einmal {cmd} im Tresor-Ordner aus (siehe Konfiguration, „Versionsverlauf“ in der Dokumentation); danach wird jede Änderung hier aufbewahrt.",
  "Memora keeps it in one place:": "Memora hält es an einem Ort:",
  "Memora saves every note as a plain Markdown file on the machine it runs on. Nothing is locked in: open the files in any editor, back them up, or keep them in Git.": "Memora speichert jede Notiz als schlichte Markdown-Datei auf dem Rechner, auf dem es läuft. Nichts ist eingesperrt: Öffne die Dateien in jedem Editor, sichere sie oder verwalte sie in Git.",
  "Memora speaks MCP over streamable HTTP. Apps send the key in the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Memora spricht MCP über Streamable HTTP. Apps senden den Schlüssel im Header <code>Authorization: Bearer &lt;key&gt;</code>.",
  "Memora stops on the machine it runs on. Your notes stay safe on disk.": "Memora hält auf dem Rechner an, auf dem es läuft. Deine Notizen bleiben sicher auf der Festplatte.",
  "Memora version": "Memora-Version",
  "Memora v{latest} is available. This server runs v{current}.": "Memora v{latest} ist verfügbar. Dieser Server läuft mit v{current}.",
  "Memora v{version} is available": "Memora v{version} ist verfügbar",
  "Memora, open Overview": "Memora, Übersicht öffnen",
  "Memora: a notes vault you host yourself, with an agent that tidies it.": "Memora: ein Notizen-Tresor, den du selbst hostest, mit einem Agenten, der ihn aufräumt.",
  "Memory used: {used} of {win}": "Genutzter Speicher: {used} von {win}",
  "Mentioned in": "Erwähnt in",
  "Mentions": "Erwähnungen",
  "Menus that fit": "Menüs, die passen",
  "Menus that fit where you are, an archive you can search, softer progress and due dates, and steps you can tick on the card.": "Menüs, die dazu passen, wo du bist, ein durchsuchbares Archiv, dezentere Fortschritts- und Fälligkeitsanzeigen und Schritte, die du auf der Karte abhaken kannst.",
  "Menus, tidied": "Aufgeräumte Menüs",
