  "Messaged {agent}": "{agent} benachrichtigt",
  "Messages and the message box line up exactly in every width, the model picker has its own surface, the fleeting chat fits phones, and a question's options never slide away as you tap them.": "Nachrichten und Eingabefeld schließen in jeder Breite exakt bündig ab, die Modellauswahl hat ihre eigene Fläche, der flüchtige Chat passt aufs Handy, und die Optionen einer Frage verrutschen beim Antippen nicht mehr.",
  "Middle-drag": "Mittelklick-Ziehen",
  "Midnight": "Mitternacht",
  "Minimap": "Minikarte",
  "Minimap: click or drag to move the view": "Minikarte: klicken oder ziehen, um die Ansicht zu bewegen",
  "Mist": "Nebel",
  "Mnemo (AI agent)": "Mnemo (KI-Agent)",
  "Mnemo and agents can do on a board everything you can, over MCP, behind four Kanban permission switches that follow Ask first, Auto and Read only.": "Mnemo und Agenten können auf einem Board alles tun, was du kannst, über MCP, hinter vier Kanban-Berechtigungsschaltern, die Erst fragen, Auto und Nur lesen folgen.",
  "Mnemo button hidden. Show it again from More, Show the Mnemo button.": "Mnemo-Button ausgeblendet. Zeige ihn wieder unter Mehr, Mnemo-Button anzeigen.",
  "Mnemo goes on without sub-agents": "Mnemo macht ohne Sub-Agenten weiter",
  "Mnemo has no model yet: add a provider and its models in Settings, Mnemo": "Mnemo hat noch kein Modell: Füge in den Einstellungen unter Mnemo einen Anbieter und seine Modelle hinzu",
  "Mnemo is built into Memora. Connect your own AI key, then ask in plain words: it finds, writes, tags, links and tidies notes for you.": "Mnemo ist in Memora eingebaut. Verbinde deinen eigenen KI-Schlüssel und frag in einfachen Worten: Es findet, schreibt, taggt, verknüpft und ordnet Notizen für dich.",
  "Mnemo is still answering in this chat": "Mnemo antwortet in diesem Chat noch",
  "Mnemo is the agent built into Memora. Connect your own AI key and ask in plain words: it keeps your notes in order while your other apps use them.": "Mnemo ist der in Memora eingebaute Agent. Verbinde deinen eigenen KI-Schlüssel und frag in einfachen Worten: Er hält deine Notizen in Ordnung, während deine anderen Apps sie nutzen.",
  "Mnemo keeps at most {n} providers; delete one first": "Mnemo behält höchstens {n} Anbieter; lösche zuerst einen",
  "Mnemo knows what is due": "Mnemo weiß, was fällig ist",
  "Mnemo manages its sub-agents, keeps its plan with the chat, and the chat fits every screen better.": "Mnemo verwaltet seine Sub-Agenten, hält seinen Plan beim Chat, und der Chat passt besser auf jeden Bildschirm.",
  "Mnemo runs its sub-agents": "Mnemo führt seine Sub-Agenten",
  "Mnemo stopped after {n} steps; say \"continue\" to go on.": "Mnemo hat nach {n} Schritten angehalten; sag „weiter“, um fortzufahren.",
  "Mnemo's plan, live": "Mnemos Plan, live",
  "Mnemo's question sits on its own band, its answers below as rows to tap, as many as the question needs.": "Die Frage von Mnemo steht auf einem eigenen Band, die Antworten darunter als Zeilen zum Antippen, so viele, wie die Frage braucht.",
  "Mnemo, your notes agent": "Mnemo, dein Notizen-Agent",
