  "Not created yet · create it": "Noch nicht erstellt · jetzt erstellen",
  "Not created yet. Click to create it.": "Noch nicht erstellt. Klicke, um ihn zu erstellen.",
  "Not done": "Nicht fertig",
  "Not done: Mnemo is in Ask first mode, so changes wait for the owner's OK. Ask with ask_owner (say what you will change; give an option with approve: true such as \"Yes, go ahead\"), then make the change after they approve.": "Nicht ausgeführt: Mnemo ist im Modus „Erst fragen“, Änderungen warten auf das OK des Besitzers. Frag mit ask_owner (sag, was du ändern willst; gib eine Option mit approve: true an, etwa „Ja, mach weiter“) und ändere erst nach der Zustimmung.",
  "Not done: Mnemo is in Read only mode, so notes are not changed. Say what you would change; the owner can switch to Ask first or Auto in the chat.": "Nicht ausgeführt: Mnemo ist im Modus „Nur lesen“, Notizen werden nicht geändert. Sag, was du ändern würdest; der Besitzer kann im Chat auf „Erst fragen“ oder „Automatisch“ wechseln.",
  "Not done: the chat is in Ask first mode, so a sub-agent cannot change notes. Say in your answer what should change; Mnemo asks the owner.": "Nicht ausgeführt: Der Chat ist im Modus „Erst fragen“, ein Sub-Agent kann keine Notizen ändern. Sag in deiner Antwort, was sich ändern soll; Mnemo fragt den Besitzer.",
  "Not done: the owner switched {tool} off for Mnemo (Settings, Mnemo).": "Nicht ausgeführt: Der Besitzer hat {tool} für Mnemo ausgeschaltet (Einstellungen, Mnemo).",
  "Not done: the owner switched {tool} off for sub-agents (Settings, Mnemo).": "Nicht ausgeführt: Der Besitzer hat {tool} für Sub-Agenten ausgeschaltet (Einstellungen, Mnemo).",
  "Not finished: the owner cut this reply before the tool returned.": "Nicht abgeschlossen: Der Besitzer hat diese Antwort abgebrochen, bevor das Tool zurückkam.",
  "Not found": "Nicht gefunden",
  "Not from AI apps": "Nicht aus KI-Apps",
  "Not in your models": "Nicht in deinen Modellen",
  "Not kept · gone when you leave it": "Nicht gespeichert · weg, sobald du ihn verlässt",
  "Not kept: nothing is learned about the owner here.": "Nicht gemerkt: Hier wird nichts über den Besitzer gelernt.",
  "Not known yet": "Noch nicht bekannt",
