  "Not started: \"{name}\" fits more than one model or none exactly. Close ones: {list}. Ask the owner which, or give the exact id.": "Nicht gestartet: „{name}“ passt auf mehr als ein Modell oder auf keins genau. Ähnliche: {list}. Frag den Besitzer, welches, oder gib die genaue ID an.",
  "Not started: there is no model \"{name}\" here. Tell the owner, or leave model out to use their default model.": "Nicht gestartet: Hier gibt es kein Modell „{name}“. Sag es dem Besitzer oder lass model weg, um sein Standardmodell zu nutzen.",
