  "Notes": "Notizen",
  "Notes and boards share one page frame with the same spacing on phones, tablets and desktops, and the links at the foot of a note share one tidy look that folds away.": "Notizen und Boards teilen sich einen Seitenrahmen mit denselben Abständen auf Handys, Tablets und Desktops, und die Links am Fuß einer Notiz haben ein einheitliches, aufgeräumtes Aussehen und lassen sich einklappen.",
  "Notes and boards, connected": "Notizen und Boards, verbunden",
  "Notes and images in the notes folder.": "Notizen und Bilder im Notizordner.",
  "Notes and the links between them show up here as a map. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Notizen und die Links dazwischen erscheinen hier als Karte. Die Anleitung zeigt, wie eine KI ihr Wissen hier speichert oder wie du selbst eine Notiz schreibst.",
  "Notes appear as the AI saves them and light up the brain. This page turns into your dashboard when the first note arrives.": "Notizen erscheinen, sobald die KI sie speichert, und lassen das Gehirn aufleuchten. Diese Seite wird zu deinem Dashboard, sobald die erste Notiz ankommt.",
  "Notes are not a password manager.": "Notizen sind kein Passwortmanager.",
  "Notes changed in the app or in the folder": "In der App oder im Ordner geänderte Notizen",
  "Notes folder": "Notizordner",
  "Notes folder switched": "Notizordner gewechselt",
  "Notes from {name}": "Notizen von {name}",
  "Notes in the Obsidian Kanban format open as boards. Drag cards and lanes with a mouse or a finger, and every change lands in the note’s history.": "Notizen im Format Obsidian Kanban öffnen sich als Boards. Zieh Karten und Spalten mit der Maus oder dem Finger, und jede Änderung landet im Verlauf der Notiz.",
  "Notes in the current folder are not moved, copied or deleted. You can switch back here at any time.": "Notizen im aktuellen Ordner werden nicht verschoben, kopiert oder gelöscht. Du kannst jederzeit hier zurückwechseln.",
  "Notes inside a folder": "Notizen in einem Ordner",
  "Notes it found": "Gefundene Notizen",
  "Notes it saved": "Gespeicherte Notizen",
  "Notes must carry": "Notizen müssen tragen",
  "Notes tagged #{tag}": "Notizen mit #{tag}",
  "Notes that carry at least one tag": "Notizen mit mindestens einem Tag",
  "Notes that carry every tag": "Notizen mit allen Tags",
  "Notes that link nowhere and are linked from nowhere.": "Notizen ohne ausgehende und eingehende Links.",
  "Notes touched": "Bearbeitete Notizen",
  "Notes with a tag; the start of the tag is enough": "Notizen mit einem Tag; der Anfang des Tags genügt",
  "Notes you delete wait here, so you can bring them back.": "Notizen, die du löschst, warten hier, damit du sie zurückholen kannst.",
  "Notes you or your AIs write show up here, newest first.": "Notizen, die du oder deine KIs schreiben, erscheinen hier, neueste zuerst.",
  "Notes, folders and images in this chat": "Notizen, Ordner und Bilder in diesem Chat",
