  "Nothing due today": "Heute ist nichts fällig",
  "Nothing else in the last 24 hours.": "Sonst nichts in den letzten 24 Stunden.",
  "Nothing from {name} in the last 24 hours.": "Nichts von {name} in den letzten 24 Stunden.",
  "Nothing here": "Nichts hier",
  "Nothing hidden yet: tick the agents to hide it from. Right now all {n} agents can see it.": "Noch nichts ausgeblendet: Hake die Agenten ab, vor denen es verborgen werden soll. Gerade können alle {n} Agenten es sehen.",
  "Nothing hidden yet: tick the agents to hide it from. Right now the only agent can see it.": "Noch nichts ausgeblendet: Hake die Agenten ab, vor denen es verborgen werden soll. Gerade kann der einzige Agent es sehen.",
  "Nothing in 24h": "Nichts in 24 Std.",
  "Nothing in note names, folders or text, and nothing spelled close to it. Try fewer letters, another spelling, or a word from inside a note.": "Nichts in Notiznamen, Ordnern oder Text, und nichts mit ähnlicher Schreibweise. Versuche weniger Buchstaben, eine andere Schreibweise oder ein Wort aus einer Notiz.",
  "Nothing in the last 24 hours. What your AIs do shows up here as it happens.": "Nichts in den letzten 24 Stunden. Was deine KIs tun, erscheint hier, sobald es passiert.",
  "Nothing in the log goes by “{name}”. Showing all activity.": "Nichts im Protokoll läuft unter „{name}“. Gesamte Aktivität wird gezeigt.",
  "Nothing in this range": "Nichts in diesem Zeitraum",
  "Nothing in your chats says “{query}”.": "In deinen Chats steht nichts zu „{query}“.",
  "Nothing is allowed. Turn something on, or pause the agent instead.": "Nichts ist erlaubt. Schalte etwas ein oder pausiere stattdessen den Agenten.",
  "Nothing is lost: the current text stays in the history as v{n}, so you can switch back at any time.": "Nichts geht verloren: Der aktuelle Text bleibt als v{n} im Verlauf, sodass du jederzeit zurückwechseln kannst.",
