  "Notifications": "Benachrichtigungen",
  "Notifications are blocked for this site. Allow them in the browser settings, then try again.": "Benachrichtigungen sind für diese Website blockiert. Erlaube sie in den Browsereinstellungen und versuche es erneut.",
  "Now": "Jetzt",
  "Now ask {name} to save what it knows": "Bitte jetzt {name}, zu speichern, was es weiß",
  "Nudge": "Anstupsen",
  "OK": "OK",
  "Ocean": "Ozean",
  "Off": "Aus",
  "Off for every AI.": "Für jede KI aus.",
  "Off for every agent": "Für jeden Agenten aus",
  "Off: its models are hidden in chats": "Aus: Seine Modelle sind in Chats ausgeblendet",
  "Off: tap to switch on": "Aus: Tippen zum Einschalten",
  "Offline": "Offline",
  "Offline · Memora": "Offline · Memora",
  "Offline, retrying": "Offline, neuer Versuch",
  "Older Gemini CLI without <code>gemini mcp add</code>: add the server to <code>~/.gemini/settings.json</code> under <code>mcpServers</code>, with <code>httpUrl</code> and the same header.": "Älteres Gemini CLI ohne <code>gemini mcp add</code>: Füge den Server in <code>~/.gemini/settings.json</code> unter <code>mcpServers</code> hinzu, mit <code>httpUrl</code> und demselben Header.",
  "Older changes stay in History.": "Ältere Änderungen bleiben im Verlauf.",
  "Older messages were left out to fit the model's context.": "Ältere Nachrichten wurden weggelassen, damit sie in den Kontext des Modells passen.",
  "Older than 30 days": "Älter als 30 Tage",
  "Older than 7 days": "Älter als 7 Tage",
  "Older than 90 days": "Älter als 90 Tage",
  "Older versions of a note: read, compare, restore, and the trash.": "Ältere Versionen einer Notiz: lesen, vergleichen, wiederherstellen, und der Papierkorb.",
  "Oldest entry": "Ältester Eintrag",
  "On": "An",
  "On a board": "Auf einem Board",
  "On desktop, drag the edge of the chat list or the side panel to make it wider or narrower. Each keeps a minimum and remembers its width.": "Am Desktop ziehst du den Rand der Chatliste oder der Seitenleiste, um sie breiter oder schmaler zu machen. Jeder Bereich hat eine Mindestbreite und merkt sich seine Breite.",
  "On hover": "Beim Überfahren",
  "On its avatar, its sparks in the brain and every activity row.": "An seinem Avatar, seinen Funken im Gehirn und in jeder Aktivitätszeile.",
  "On the Boards page each board has a ⋯ menu to open, rename, move, duplicate, colour or trash it. Right-click or a long press opens it too.": "Auf der Boards-Seite hat jedes Board ein ⋯-Menü zum Öffnen, Umbenennen, Verschieben, Duplizieren, Einfärben oder in den Papierkorb legen. Rechtsklick oder langes Drücken öffnet es ebenfalls.",
  "On this page": "Auf dieser Seite",
  "On: tap to switch off": "An: Tippen zum Ausschalten",
  "On: {mnemo} notes what it picks up in chats. Off: only what you add here. Saved at once.": "An: {mnemo} notiert, was es in Chats aufschnappt. Aus: nur das, was du hier hinzufügst. Wird sofort gespeichert.",
  "Once installed, the app has its own icon, opens full screen and stays reachable when the network drops.": "Einmal installiert, hat die App ein eigenes Symbol, öffnet im Vollbild und bleibt erreichbar, wenn das Netz ausfällt.",
  "Once it is connected, paste this into a new chat in that app. It tells the AI to store what it knows into Memora.": "Sobald sie verbunden ist, füge dies in einen neuen Chat in dieser App ein. Es weist die KI an, ihr Wissen in Memora zu speichern.",
  "Once its app is set up, every call shows up here as it happens.": "Sobald seine App eingerichtet ist, erscheint hier jeder Aufruf, sobald er passiert.",
  "Once {name} is connected, everything it reads, writes and searches shows up here, live.": "Sobald {name} verbunden ist, erscheint hier live alles, was es liest, schreibt und sucht.",
  "One address": "Eine Adresse",
  "One agent per app or device: its own key, its own name in Activity, turned off on its own.": "Ein Agent pro App oder Gerät: eigener Schlüssel, eigener Name in der Aktivität, einzeln abschaltbar.",
  "One click": "Ein Klick",
  "One device or connection, such as 203.0.113.7. Searching \"what is my IP\" shows yours.": "Ein Gerät oder eine Verbindung, etwa 203.0.113.7. Wenn du „what is my IP“ suchst, siehst du deine.",
  "One device or connection.": "Ein Gerät oder eine Verbindung.",
  "One folder of notes that you and every connected AI share.": "Ein Notizordner, den du und jede verbundene KI teilen.",
  "One is hidden by the folder rule.": "Einer ist durch die Ordnerregel ausgeblendet.",
  "One key per agent, its own permissions.": "Ein Schlüssel pro Agent, eigene Berechtigungen.",
  "One last step": "Ein letzter Schritt",
  "One memory every agent reads and writes, and you can see, edit and connect all of it.": "Ein Gedächtnis, das jeder Agent liest und beschreibt und das du ganz sehen, bearbeiten und verbinden kannst.",
  "One memory for every AI": "Ein Gedächtnis für jede KI",
  "One note shows this image; it will show as missing there. The version history keeps it.": "Eine Notiz zeigt dieses Bild; dort erscheint es dann als fehlend. Der Versionsverlauf behält es.",
  "One per line. They show among the suggestions on a new chat, marked Yours, and stay until you change them.": "Eine pro Zeile. Sie erscheinen unter den Vorschlägen bei einem neuen Chat, markiert als Deine, und bleiben, bis du sie änderst.",
  "One private memory that you and your AI apps share, so nothing has to be explained twice.": "Ein privates Gedächtnis, das du und deine KI-Apps teilt, damit nichts doppelt erklärt werden muss.",
  "One set of notes for every AI app": "Ein Notizbestand für jede KI-App",
  "One thin progress bar instead of stark lane bars, softer shadows, lane colours across the whole lane, and overdue shown as a stroke.": "Ein dünner Fortschrittsbalken statt harter Spaltenbalken, weichere Schatten, Spaltenfarben über die ganze Spalte und Überfälliges als Strich.",
  "Online": "Online",
  "Only PNG, JPEG, WebP and GIF images can be added": "Nur PNG-, JPEG-, WebP- und GIF-Bilder können hinzugefügt werden",
  "Only in the current version": "Nur in der aktuellen Version",
  "Only in version {n}": "Nur in Version {n}",
  "Only letters, digits and - _ / . can be used.": "Nur Buchstaben, Ziffern und - _ / . sind erlaubt.",
  "Only looks at notes; changes nothing.": "Sieht nur Notizen an; ändert nichts.",
  "Only looks things up and never writes. For agents with a read-only key.": "Schlägt nur nach und schreibt nie. Für Agenten mit schreibgeschütztem Schlüssel.",
  "Only pictures in your newest message go to the image model, and you hear of it in a short toast.": "Nur Bilder aus deiner neuesten Nachricht gehen an das Bildmodell, und du erfährst es in einem kurzen Hinweis.",
  "Only reads and answers; never changes notes": "Liest und antwortet nur; ändert nie Notizen",
  "Only the agents you pick. New agents can’t see it.": "Nur die Agenten, die du wählst. Neue Agenten können es nicht sehen.",
  "Only the first rule that fits a request counts.": "Nur die erste passende Regel einer Anfrage zählt.",
  "Only the latest questions go on the page at first; earlier ones come in as you scroll up or jump to them on the timeline.": "Zuerst kommen nur die neuesten Fragen auf die Seite; ältere folgen, wenn du nach oben scrollst oder auf der Zeitleiste hinspringst.",
  "Only the ones I pick": "Nur die, die ich wähle",
  "Only these agents": "Nur diese Agenten",
  "Only this": "Nur das",
  "Only this agent": "Nur dieser Agent",
  "Only this board uses this look.": "Nur dieses Board nutzt diesen Look.",
  "Only this note uses these settings.": "Nur diese Notiz nutzt diese Einstellungen.",
  "Only {names} can see this {what}. Every other agent, including ones added later, is blocked.": "Nur {names} können dieses Element ({what}) sehen. Jeder andere Agent, auch später hinzugefügte, ist gesperrt.",
  "Only {name}": "Nur {name}",
  "Only {n} agent can now see “{name}”": "Nur {n} Agent kann jetzt „{name}“ sehen",
  "Only {n} agents can now see “{name}”": "Nur {n} Agenten können jetzt „{name}“ sehen",
  "Only {n} chosen tool": "Nur {n} gewähltes Tool",
  "Only {n} chosen tools": "Nur {n} gewählte Tools",
