  "Past activity keeps the old name; new activity uses this one.": "Frühere Aktivität behält den alten Namen; neue Aktivität nutzt diesen.",
  "Past due dates show in a warning tint and today’s in a softer one, and the Boards page counts what is overdue. A board’s own date colours win.": "Abgelaufene Fälligkeitsdaten erscheinen in einem Warnton, das heutige in einem sanfteren, und die Boards-Seite zählt, was überfällig ist. Die eigenen Datumsfarben eines Boards haben Vorrang.",
  "Paste both into the app and save.": "Füge beides in die App ein und speichere.",
  "Paste it in a terminal and press <kbd>Enter</kbd>, then start Codex in that same terminal.": "Füge es in ein Terminal ein und drücke <kbd>Enter</kbd>, dann starte Codex im selben Terminal.",
  "Paste it in a terminal and press <kbd>Enter</kbd>. Then start Claude Code, or restart it: Memora loads by itself.": "Füge es in ein Terminal ein und drücke <kbd>Enter</kbd>. Starte dann Claude Code oder starte es neu: Memora lädt von selbst.",
  "Paste it in a terminal and press <kbd>Enter</kbd>. Then start Gemini CLI, or restart it, and type <code>/mcp</code> to see Memora.": "Füge es in ein Terminal ein und drücke <kbd>Enter</kbd>. Starte dann Gemini CLI oder starte es neu und gib <code>/mcp</code> ein, um Memora zu sehen.",
  "Paste it into the app where it asks for a key.": "Füge es in die App ein, wo sie nach einem Schlüssel fragt.",
  "Paste it into the file and save, then press <b>Refresh</b>. Memora shows up in the list.": "Füge es in die Datei ein, speichere und tippe dann auf <b>Refresh</b>. Memora erscheint in der Liste.",
  "Paste it into the file, save, and restart Claude Desktop. It needs Node.js on this computer.": "Füge es in die Datei ein, speichere und starte Claude Desktop neu. Dafür braucht es Node.js auf diesem Computer.",
