  "Save into Memora what I've shared with you about my personal life: my interests, habits, goals, the people who matter to me and things I care about. Put these notes in a folder named Private, one note per topic, and link related notes. Never save passwords, card numbers or other secrets. When you're done, tell me what you saved.": "Speichere in Memora, was ich dir über mein Privatleben erzählt habe: meine Interessen, Gewohnheiten, Ziele, die Menschen, die mir wichtig sind, und Dinge, die mir am Herzen liegen. Lege diese Notizen in einem Ordner namens Private ab, eine Notiz pro Thema, und verlinke verwandte Notizen. Speichere nie Passwörter, Kartennummern oder andere Geheimnisse. Sag mir am Ende, was du gespeichert hast.",
  "Save into Memora what you know about my work: my role, my team, the projects I'm on and where they stand, and decisions we made. Make one note per project or topic and link them together.": "Speichere in Memora, was du über meine Arbeit weißt: meine Rolle, mein Team, die Projekte, an denen ich arbeite, und wo sie stehen, und Entscheidungen, die wir getroffen haben. Mach eine Notiz pro Projekt oder Thema und verlinke sie miteinander.",
