  "Steps": "Schritte",
  "Steps are added, edited and checked as Mnemo works. Stop a reply and the plan stays as it was; it closes once every step is done.": "Schritte werden hinzugefügt, bearbeitet und abgehakt, während Mnemo arbeitet. Stoppst du eine Antwort, bleibt der Plan, wie er war; er schließt sich, sobald jeder Schritt erledigt ist.",
