  "Stopping a reply always sends the next queued message, and Scroll to bottom shows only when you are away from the end.": "Eine gestoppte Antwort schickt immer die nächste Nachricht aus der Warteschlange, und Nach unten erscheint nur, wenn du weit vom Ende entfernt bist.",
