  "Sub-agents you can steer": "Sub-Agenten, die du steuern kannst",
  "Subfolders are kept inside the destination and links to the moved notes are updated. If a name is already taken there, a number is added to it.": "Unterordner bleiben im Ziel erhalten, und Links auf die verschobenen Notizen werden aktualisiert. Ist dort ein Name schon vergeben, wird eine Nummer angehängt.",
