  "Switch tools for": "Tools umschalten für",
  "Switch tools off for Mnemo or for its sub-agents, and keep notes, folders or pictures private from it.": "Schalte Tools für Mnemo oder seine Sub-Agenten aus und halte Notizen, Ordner oder Bilder vor ihm privat.",
  "Switch tools on or off for everyone and change any agent's key and access, its own included.": "Schalte Tools für alle ein oder aus und ändere Schlüssel und Zugriff jedes Agenten, auch seinen eigenen.",
