  "Tag": "Tag",
  "Tag list cleared. It is rebuilt the next time tags are used.": "Tag-Liste geleert. Sie wird beim nächsten Tag-Gebrauch neu aufgebaut.",
  "Tag my reading notes and link them to the launch plan.": "Tagge meine Lesenotizen und verknüpfe sie mit dem Launch-Plan.",
