  "Technical details": "Technische Details",
  "Tell Mnemo about you": "Erzähl Mnemo von dir",
  "Tell {mnemo} about you": "Erzähl {mnemo} von dir",
  "Tell {mnemo} how you like things, in your own words: the language to answer in, how to name notes, folders to leave alone…": "Sag {mnemo} in deinen eigenen Worten, wie du es magst: in welcher Sprache es antworten soll, wie Notizen heißen sollen, welche Ordner es in Ruhe lässt …",
  "Test": "Testen",
  "Test an address": "Eine Adresse testen",
