  "This folder has {nodes}.": "Dieser Ordner hat {nodes}.",
  "This folder has {nodes}: {direct} directly inside and the rest in {subs}.": "Dieser Ordner hat {nodes}: {direct} direkt darin und der Rest in {subs}.",
  "This folder is empty": "Dieser Ordner ist leer",
  "This job stays off": "Diese Aufgabe bleibt aus",
  "This keeps out everyone that no rule above it lets in, including you, unless a rule allowing your own address comes first.": "Das hält alle draußen, die keine Regel darüber hereinlässt, dich eingeschlossen, außer eine Regel für deine eigene Adresse steht davor.",
  "This key is shown once. Copy it now and keep it private.": "Dieser Schlüssel wird einmal gezeigt. Kopiere ihn jetzt und halte ihn privat.",
  "This model cannot read pictures": "Dieses Modell kann keine Bilder lesen",
  "This note": "Diese Notiz",
  "This note does not link to other notes yet.": "Diese Notiz verlinkt noch nicht auf andere Notizen.",
  "This note does not link to other notes yet. Type [[ while editing to add a link.": "Diese Notiz verlinkt noch nicht auf andere Notizen. Tippe beim Bearbeiten [[, um einen Link hinzuzufügen.",
  "This note has changes that are not saved yet.": "Diese Notiz hat Änderungen, die noch nicht gespeichert sind.",
  "This note has its own settings, which win over these.": "Diese Notiz hat eigene Einstellungen, die Vorrang vor diesen haben.",
  "This note has no headings yet.": "Diese Notiz hat noch keine Überschriften.",
  "This note has not been saved to the history yet. The next change starts it.": "Diese Notiz wurde noch nicht im Verlauf gespeichert. Die nächste Änderung legt ihn an.",
