  "This note is empty.": "Diese Notiz ist leer.",
  "This note is empty. {start} or press {key}.": "Diese Notiz ist leer. {start} oder drücke {key}.",
  "This note is removed from the vault for good, with its text, tags and links. Every earlier version is erased from the version history too, so no one, agents included, can read it again.": "Diese Notiz wird endgültig aus dem Tresor entfernt, samt Text, Tags und Links. Auch jede frühere Version wird aus dem Verlauf gelöscht, sodass niemand, auch keine Agenten, sie je wieder lesen kann.",
  "This note links to nothing yet.": "Diese Notiz verlinkt noch auf nichts.",
  "This note only": "Nur diese Notiz",
  "This note shows no image of its folder yet.": "Diese Notiz zeigt noch kein Bild aus ihrem Ordner.",
  "This notes folder is empty": "Dieser Notizordner ist leer",
  "This page continues on its own when the pause ends.": "Diese Seite geht von selbst weiter, wenn die Pause endet.",
  "This page moves on by itself.": "Diese Seite geht von selbst weiter.",
  "This page notices by itself as soon as {app} connects. Keep it open.": "Diese Seite bemerkt von selbst, sobald {app} sich verbindet. Lass sie offen.",
  "This server is run by systemd, which starts it again a few seconds later. To keep it stopped, run {cmd} on the server instead.": "Dieser Server wird von systemd betrieben, das ihn einige Sekunden später neu startet. Um ihn gestoppt zu halten, führe stattdessen {cmd} auf dem Server aus.",
  "This server runs in Docker, which may start it again. To keep it stopped, run {cmd} on the host instead.": "Dieser Server läuft in Docker, das ihn eventuell neu startet. Um ihn gestoppt zu halten, führe stattdessen {cmd} auf dem Host aus.",
  "This vault has no tags yet. Add {inline} or a {line} line to a note.": "Dieser Tresor hat noch keine Tags. Füge {inline} oder eine {line}-Zeile in eine Notiz ein.",
  "This vault is private. Sign in to see your notes, the brain and agent activity.": "Dieser Tresor ist privat. Melde dich an, um deine Notizen, das Gehirn und die Agentenaktivität zu sehen.",
  "Thought it through": "Durchdacht",
  "Through a tunnel or a reverse proxy, from anywhere.": "Über einen Tunnel oder Reverse-Proxy, von überall.",
