  "To do": "Zu erledigen",
  "To start it again, someone must run {cmd} (or start its service) on the machine it runs on. This page cannot start it.": "Um ihn wieder zu starten, muss jemand {cmd} (oder seinen Dienst) auf dem Rechner ausführen, auf dem er läuft. Diese Seite kann ihn nicht starten.",
  "To-dos, follow-ups, checks that a note is well formed, and the pinned notes and folders.": "To-dos, Rückfragen, Prüfungen, ob eine Notiz korrekt aufgebaut ist, und die angehefteten Notizen und Ordner.",
  "Today": "Heute",
  "Together": "Zusammen",
  "Toggle sidebar": "Seitenleiste ein-/ausblenden",
