  "Too many attempts": "Zu viele Versuche",
  "Too many failed attempts. Try again in 1 minute.": "Zu viele Fehlversuche. Versuch es in 1 Minute erneut.",
  "Too many failed attempts. Try again in {n} minutes.": "Zu viele Fehlversuche. Versuch es in {n} Minuten erneut.",
  "Too many requests. Slow down and try again shortly.": "Zu viele Anfragen. Etwas langsamer und gleich noch einmal versuchen.",
  "Too many requests. Wait a few seconds and try again.": "Zu viele Anfragen. Warte ein paar Sekunden und versuch es erneut.",
  "Too many wrong codes, so this reset code no longer works. Run memora-cli reset-password on the server for a new one.": "Zu viele falsche Codes, daher funktioniert dieser Reset-Code nicht mehr. Führe memora-cli reset-password auf dem Server aus, um einen neuen zu bekommen.",
  "Too many wrong codes, so this setup code no longer works. Run memora-cli setup on the server for a new one.": "Zu viele falsche Codes, daher funktioniert dieser Einrichtungscode nicht mehr. Führe memora-cli setup auf dem Server aus, um einen neuen zu bekommen.",
  "Tool": "Tool",
