  "Tools added later stay blocked for this agent.": "Später hinzugefügte Tools bleiben für diesen Agenten gesperrt.",
  "Tools run under the name {mnemo} so every action shows in Activity. Tap a tool to switch it off or on, for {mnemo} itself or for its sub-agents. A tool switched off on the Tools page is off for both. Saved at once.": "Tools laufen unter dem Namen {mnemo}, sodass jede Aktion in der Aktivität erscheint. Tippe auf ein Tool, um es ein- oder auszuschalten, für {mnemo} selbst oder für seine Sub-Agenten. Ein auf der Tools-Seite ausgeschaltetes Tool ist für beide aus. Wird sofort gespeichert.",
