  "Trash": "Papierkorb",
  "Trash a board or a note from the Boards page, the board itself or the note lists, then bring it back with Undo in the toast.": "Leg ein Board oder eine Notiz von der Boards-Seite, vom Board selbst oder aus den Notizlisten in den Papierkorb und hol es mit Rückgängig im Hinweis zurück.",
