  "Turn on at least one thing it may do, or turn the agent off instead.": "Schalte mindestens eine Funktion ein, die er darf, oder schalte stattdessen den Agenten aus.",
  "Turn on due date reminders in Settings: one notification when a card falls due and one a day for what is overdue. The Boards item counts what is late.": "Schalte Erinnerungen an Fälligkeitsdaten in den Einstellungen ein: eine Benachrichtigung, wenn eine Karte fällig wird, und eine pro Tag für Überfälliges. Der Eintrag Boards zählt, was überfällig ist.",
