  "When a chat's model fails (the provider is down, busy or out of credit), {mnemo} carries on with these, in this order, up to five. With none left, the chat shows the error and Try again. Saved at once.": "Wenn das Modell eines Chats ausfällt (der Anbieter ist down, ausgelastet oder ohne Guthaben), macht {mnemo} mit diesen in dieser Reihenfolge weiter, bis zu fünf. Ist keines mehr übrig, zeigt der Chat den Fehler und Erneut versuchen. Wird sofort gespeichert.",
