  "You already have {who} for {app}. A separate agent per device keeps activity apart, so go ahead if this is another computer or setup.": "Du hast schon {who} für {app}. Ein eigener Agent pro Gerät hält die Aktivität getrennt, mach also ruhig weiter, wenn dies ein anderer Computer oder ein anderes Setup ist.",
