  "You have unsaved changes from {when} on this device.": "Du hast ungespeicherte Änderungen von {when} auf diesem Gerät.",
  "You now have long-term memory through Memora. Save into Memora everything you know about me from our conversations: who I am, my work, the projects I'm on, my preferences and important decisions. Make one note per topic in a fitting folder, and link notes that belong together. When you're done, tell me what you saved.": "Du hast jetzt ein Langzeitgedächtnis durch Memora. Speichere in Memora alles, was du aus unseren Gesprächen über mich weißt: wer ich bin, meine Arbeit, die Projekte, an denen ich arbeite, meine Präferenzen und wichtige Entscheidungen. Mach eine Notiz pro Thema in einem passenden Ordner und verlinke zusammengehörige Notizen. Sag mir am Ende, was du gespeichert hast.",
