  "Your connected AI works in this folder now. Ask one to save what it knows here, or write a note yourself. Switched folders by mistake? Switch back under Settings, Notes folder.": "Deine verbundene KI arbeitet jetzt in diesem Ordner. Bitte eine, hier zu speichern, was sie weiß, oder schreib selbst eine Notiz. Versehentlich den Ordner gewechselt? Wechsle unter Einstellungen, Notizordner zurück.",
