  "{mnemo} starts sub-agents by itself when a task splits well; there is nothing to set up. They run on your default model, then the fallbacks, unless you name a model in the chat. Follow them, and switch their model, in Agents at the top right of the chat. They use tokens of their own, so in Ask first {mnemo} asks and says roughly how many; in Auto they just run. Saved at once.": "{mnemo} startet Sub-Agenten selbst, wenn sich eine Aufgabe gut aufteilen lässt; es gibt nichts einzurichten. Sie laufen mit deinem Standardmodell, dann den Ausweichmodellen, es sei denn, du nennst im Chat ein Modell. Verfolge sie und wechsle ihr Modell unter Agenten oben rechts im Chat. Sie verbrauchen eigene Tokens, daher fragt {mnemo} bei Erst fragen nach und nennt ungefähr wie viele; bei Auto laufen sie einfach. Wird sofort gespeichert.",
  "{mnemo} stopped it": "{mnemo} hat ihn gestoppt",
  "{mnemo} will keep that in mind": "{mnemo} merkt sich das",
  "{mnemo} writes new suggestions from your recent notes (yours stay)": "{mnemo} schreibt neue Vorschläge aus deinen letzten Notizen (deine bleiben)",
  "{mnemo}'s own ({n})": "Eigene von {mnemo} ({n})",
  "{mnemo}'s own notes on how to talk to you, read in every chat. Click one to change it.": "{mnemo}s eigene Notizen dazu, wie es mit dir reden soll, in jedem Chat gelesen. Klicke auf eine, um sie zu ändern.",
  "{mnemo}, your notes agent": "{mnemo}, dein Notizen-Agent",
  "{mnemo}: {text}": "{mnemo}: {text}",
  "{model} cannot look at images; it got their names instead. Set a model that reads images in Settings to have them seen.": "{model} kann keine Bilder ansehen; es bekam stattdessen ihre Namen. Lege in den Einstellungen ein Modell fest, das Bilder liest, damit sie gesehen werden.",
  "{model} cannot look at images; the image model described them for it.": "{model} kann keine Bilder ansehen; das Bildmodell hat sie für es beschrieben.",
  "{model} cannot read pictures, so it only gets their names. Set a model that reads images, or switch this chat's model.": "{model} kann keine Bilder lesen und bekommt daher nur ihre Namen. Lege ein Modell fest, das Bilder liest, oder wechsle das Modell dieses Chats.",
  "{model} cannot read pictures, so it only got their names. Set a model that reads images, or switch this chat's model.": "{model} kann keine Bilder lesen und bekam daher nur ihre Namen. Lege ein Modell fest, das Bilder liest, oder wechsle das Modell dieses Chats.",
  "{model} cannot read pictures, so the image model looked at them for it.": "{model} kann keine Bilder lesen, daher hat das Bildmodell sie für es angesehen.",
  "{model} cannot read pictures, so the image model looks at them for it.": "{model} kann keine Bilder lesen, daher sieht das Bildmodell sie für es an.",
  "{model} did not answer ({why}); trying again in {wait} s ({n}/{total})…": "{model} hat nicht geantwortet ({why}); neuer Versuch in {wait} s ({n}/{total})…",
  "{model} is answering": "{model} antwortet",
  "{model} is the default for new chats": "{model} ist der Standard für neue Chats",
  "{model} takes over from {agent}'s next step (it is working now), and answers its follow-ups in this chat. It may work a little differently from {prev}.": "{model} übernimmt ab dem nächsten Schritt von {agent} (er arbeitet gerade) und beantwortet seine Rückfragen in diesem Chat. Es arbeitet vielleicht etwas anders als {prev}.",
  "{model} takes over from {agent}'s next step, and answers its follow-ups in this chat. It may work a little differently from {prev}.": "{model} übernimmt ab dem nächsten Schritt von {agent} und beantwortet seine Rückfragen in diesem Chat. Es arbeitet vielleicht etwas anders als {prev}.",
